@Service
public class FileStorageService {

    private static final String DEFAULT_ORIGINAL_NAME = "file";

    private final Path storageRoot;
    private final FileRecordMapper fileRecordMapper;

    public FileStorageService(@Value("${dataflow.storage.root}") String storageRoot,
